import streamlit as st
import pandas as pd

st.set_page_config(page_title="HDFS Anomaly Detector", layout="wide")
st.title("🚨 Distributed HDFS Behavioral Anomaly Dashboard")
st.markdown("K-Means anomaly detection results powered by PySpark and YARN.")

# Load the data generated by the Spark job
try:
    df = pd.read_csv("/home/hduser/anomalies.csv")
    
    col1, col2 = st.columns([1, 2])
    
    with col1:
        st.subheader("Top Critical Windows")
        st.dataframe(df.style.highlight_max(subset=['AnomalyScore'], color='#ff4b4b'))
        
    with col2:
        st.subheader("Anomaly Severity vs Event Frequency")
        st.scatter_chart(
            data=df,
            x="EventFrequency",
            y="AnomalyScore",
            color="#ff4b4b",
            size="AnomalyScore"
        )
        
except FileNotFoundError:
    st.warning("No anomaly data found. Please run the PySpark job first.")
